/**
 * EP1 Tier A: the TS ASS builders (lib/clips/render-plan) emit the worker's bytes.
 * Goldens: worker/tests/fixtures/render_plan/*.ass, generated by worker/scripts/gen_render_plan_goldens.py
 * and asserted on the worker side by worker/tests/test_render_plan_goldens.py.
 */
import { readFileSync } from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'
import { describe, expect, it } from 'vitest'
import { buildCaptionsAss } from '@/lib/clips/render-plan/captions-ass'
import { buildTextItemsAss } from '@/lib/clips/render-plan/text-items-ass'
import { hookAssForEdits } from '@/lib/clips/render-plan/hook-ass'
import { buildTitleAss } from '@/lib/clips/render-plan/title-ass'
import { headlineAssContent } from '@/lib/clips/render-plan/headline-ass'
import { badgeRenderState } from '@/lib/clips/render-plan/badge'
import { pyFixed, pyRound, pyRoundN, pyFloatStr } from '@/lib/clips/render-plan/py'
import type { ClipEditsV2 } from '@/lib/clips/edits'

const here = path.dirname(fileURLToPath(import.meta.url))
const FIX = path.resolve(here, '../../worker/tests/fixtures/render_plan')
type Case = Record<string, any> & { name: string; kind: string }
const CASES = JSON.parse(readFileSync(path.join(FIX, 'cases.json'), 'utf8')) as { ass: Case[]; badge: Case[] }
const golden = (n: string) => readFileSync(path.join(FIX, `${n}.ass`), 'utf8')

function render(c: Case): string {
  if (c.kind === 'captions') return buildCaptionsAss(c.words, c.captions, c.w, c.h)
  if (c.kind === 'text_items') return buildTextItemsAss(c.edits, c.w, c.h) ?? ''
  if (c.kind === 'hook') return hookAssForEdits(c.edits, c.w, c.h) ?? ''
  if (c.kind === 'title')
    return buildTitleAss({ text: c.text, playW: c.w, playH: c.h, rect: c.rect, kind: c.bgKind, textColor: c.textColor, font: c.font, durationMs: c.durationMs })
  if (c.kind === 'headline')
    return headlineAssContent({
      headline: c.headline, playW: c.w, playH: c.h, barH: c.barH, durationMs: c.durationMs, barY: c.barY ?? 0,
      fitTop: Boolean(c.fitTop), textColor: c.textColor, headlineStyle: c.headlineStyle, textBoxX: c.textBoxX ?? null, textBoxW: c.textBoxW ?? null,
    })
  throw new Error(c.kind)
}

describe('EP1 render plan: TS ASS == worker ASS (byte for byte)', () => {
  for (const c of CASES.ass) {
    it(c.name, () => {
      expect(render(c)).toBe(golden(c.name))
    })
  }
})

describe('EP1 badge visibility rule == worker badge_render_state', () => {
  const expected = JSON.parse(readFileSync(path.join(FIX, 'badge_expected.json'), 'utf8')) as { name: string; state: unknown }[]
  for (const c of CASES.badge) {
    it(c.name, () => {
      const want = expected.find((e) => e.name === c.name)!.state
      expect(badgeRenderState(c.edits as ClipEditsV2, { templateMode: Boolean(c.templateMode) })).toEqual(want)
    })
  }
})

describe('Python number formatting', () => {
  it('round half-even on the exact binary value', () => {
    expect([0.5, 1.5, 2.5, -0.5, 2.675].map(pyRound)).toEqual([0, 2, 2, 0, 3])
    expect(pyRoundN(2.675, 2)).toBe(2.67)
    expect(pyRoundN(0.125, 2)).toBe(0.12)
    expect(pyFixed(0.125, 2)).toBe('0.12')
    expect(pyFixed(1.005, 2)).toBe('1.00')
    expect(pyFloatStr(8)).toBe('8.0')
    expect(pyFloatStr(pyRoundN(-0.001, 2))).toBe('-0.0')
  })
})
